export const MIGRATIONS: Migration[] = [
  {
    "id": "034_dedupe_chargers_by_site",
    "description": "Dedupe helper functions (defines only; run the dedupe separately)",
    "sql": "-- =============================================================================\n-- 034: collapse duplicate chargers that migration 021 could not reach.\n--\n-- 021 only merged rows sharing a ~11 m grid cell (coordinates rounded to 4\n-- decimals). Open Charge Map community submissions for one physical site are\n-- routinely 20–50 m apart, so those survived as separate rows and the map drew\n-- them as two pins for one station.\n--\n-- Implementation notes (an earlier ST_ClusterDBSCAN version of this migration\n-- timed out and is deliberately not used):\n--\n--   * ST_ClusterDBSCAN is a window function — it materialises the whole table\n--     in one window and cannot use the GiST index, so on a table holding\n--     several bulk-imported countries it exceeds the statement timeout.\n--     ST_DWithin on the geography column is index-accelerated\n--     (chargers_geo_gix, migration 017) and stays fast.\n--   * DBSCAN also had to express the radius in degrees, which is only correct\n--     north-south: at 41°N a degree of longitude is ~84 km, so a fixed degree\n--     eps traced an ellipse ~40 m tall and ~30 m wide. ST_DWithin on geography\n--     measures true metres in every direction.\n--\n-- A row is deleted when a strictly better row (higher confidence, then more\n-- sources, then greater id — a total order, so exactly one row of any pair\n-- survives) sits within SAME_SITE_M = 40 m and carries a compatible operator.\n-- Rows with no operator are compared against each other only, so a genuinely\n-- co-located different network is never collapsed.\n--\n-- Chains collapse transitively (A–B and B–C both within 40 m merges all three\n-- even if A–C is 70 m apart). That matches how the runtime clusters arrivals in\n-- src/lib/chargers/dedup.ts and is bounded by the 40 m step.\n--\n-- charger_connectors and charger_sources cascade-delete with the removed rows.\n-- On the next ingest the freed source refs fail the definite (source, ref)\n-- match and re-attach to the survivor via the same-site merge, so this stays\n-- collapsed rather than reappearing.\n--\n-- Idempotent: re-running is a no-op once every site holds a single row.\n-- =============================================================================\n\n-- p_limit bounds a single call so a very large group can be worked through in\n-- batches: re-run the same call until it returns 0. Rows whose country is NULL\n-- are usually the largest group (sources that do not report a country), so that\n-- pass in particular wants a batch limit.\n--\n-- The country predicate is branched rather than written as a single\n-- `country is not distinct from p_country`: that operator has no btree operator\n-- class, so it forces a sequential scan over the whole table. `= p_country` and\n-- `is null` both use chargers_country (btree indexes do store NULLs).\ncreate or replace function public.dedupe_chargers_by_site(\n  p_country char(2),\n  p_limit   integer default 200000\n)\nreturns integer\nlanguage plpgsql\nsecurity definer\nset search_path = public\nas $$\ndeclare\n  v_deleted integer;\nbegin\n  if p_country is null then\n    delete from chargers\n    where id in (\n      select c.id\n      from chargers c\n      where c.country is null\n        and exists (\n          select 1\n          from chargers k\n          where k.id <> c.id\n            and st_dwithin(c.location, k.location, 40)\n            and coalesce(k.operator_id, '~unknown') = coalesce(c.operator_id, '~unknown')\n            and (k.confidence, k.source_count, k.id) > (c.confidence, c.source_count, c.id)\n        )\n      limit p_limit\n    );\n  else\n    delete from chargers\n    where id in (\n      select c.id\n      from chargers c\n      where c.country = p_country\n        and exists (\n          select 1\n          from chargers k\n          where k.id <> c.id\n            and st_dwithin(c.location, k.location, 40)\n            and coalesce(k.operator_id, '~unknown') = coalesce(c.operator_id, '~unknown')\n            and (k.confidence, k.source_count, k.id) > (c.confidence, c.source_count, c.id)\n        )\n      limit p_limit\n    );\n  end if;\n\n  get diagnostics v_deleted = row_count;\n  return v_deleted;\nend;\n$$;\n\n-- Country-agnostic batched pass. Prefer this: `country` is NULL on the large\n-- majority of rows, because Overpass/OSM data carries no country (addr:country\n-- is rarely tagged — country is implied geographically), so partitioning the\n-- work by country leaves most of the table untouched and pushes everything into\n-- one oversized NULL pass. Re-run until it returns 0.\ncreate or replace function public.dedupe_chargers_batch(p_limit integer default 2000)\nreturns integer\nlanguage plpgsql\nsecurity definer\nset search_path = public\nas $$\ndeclare\n  v_deleted integer;\nbegin\n  delete from chargers\n  where id in (\n    select c.id\n    from chargers c\n    where exists (\n      select 1\n      from chargers k\n      where k.id <> c.id\n        and st_dwithin(c.location, k.location, 40)\n        and coalesce(k.operator_id, '~unknown') = coalesce(c.operator_id, '~unknown')\n        and (k.confidence, k.source_count, k.id) > (c.confidence, c.source_count, c.id)\n    )\n    limit p_limit\n  );\n\n  get diagnostics v_deleted = row_count;\n  return v_deleted;\nend;\n$$;\n\n-- Applying this migration only defines the helpers; it does not delete\n-- anything. Collapsing duplicates is an operational action, run deliberately:\n--\n--   select public.dedupe_chargers_batch(2000);   -- repeat until it returns 0\n--\n-- The per-country variant is for targeting one country on purpose. On this\n-- dataset most rows carry no country (Overpass/OSM does not tag one), so the\n-- batch form above is the one that actually reaches them:\n--\n--   select public.dedupe_chargers_by_site('RO');\n--   select public.dedupe_chargers_by_site(null, 2000);\n"
  },
  {
    "id": "035_debug_stats_functions",
    "description": "Aggregate helpers this debug panel reads",
    "sql": "-- =============================================================================\n-- 035: read-only aggregate helpers for the admin debug panel.\n--\n-- PostgREST cannot express these as a plain select (count with FILTER, count\n-- DISTINCT), and pulling the rows into the app to count them client-side would\n-- mean shipping the whole charger table. Both functions are read-only and\n-- return aggregates only — no charger rows leave the database through them.\n--\n-- security definer so the aggregates work regardless of the caller's RLS view;\n-- the API route in front of them is admin-gated.\n-- =============================================================================\n\ncreate or replace function public.debug_charger_stats()\nreturns table (\n  total       bigint,\n  no_country  bigint,\n  operators   bigint,\n  no_operator bigint\n)\nlanguage sql\nstable\nsecurity definer\nset search_path = public\nas $$\n  select\n    count(*)                                        as total,\n    count(*) filter (where country is null)          as no_country,\n    count(distinct operator_id)                      as operators,\n    count(*) filter (where operator_id is null)      as no_operator\n  from chargers;\n$$;\n\ncreate or replace function public.debug_source_counts()\nreturns table (\n  source text,\n  rows   bigint\n)\nlanguage sql\nstable\nsecurity definer\nset search_path = public\nas $$\n  select source, count(*) as rows\n  from charger_sources\n  group by source\n  order by count(*) desc;\n$$;\n\nrevoke all on function public.debug_charger_stats() from public, anon;\nrevoke all on function public.debug_source_counts() from public, anon;\ngrant execute on function public.debug_charger_stats() to service_role;\ngrant execute on function public.debug_source_counts() to service_role;\n"
  },
  {
    "id": "036_upsert_dedupe_source_refs",
    "description": "Guard the batch upsert against a repeated source ref",
    "sql": "-- =============================================================================\n-- 036: make the batch upsert tolerate a repeated (source, source_ref).\n--\n-- charger_sources is written with ON CONFLICT DO UPDATE. Postgres raises\n-- \"ON CONFLICT DO UPDATE command cannot affect row a second time\" when one\n-- statement presents the same conflict key twice, and that aborts the whole\n-- RPC — so one malformed cluster discarded a chunk of up to 200 chargers and\n-- the run recorded \"all upserts failed\".\n--\n-- The producing bug is fixed in src/lib/chargers/dedup.ts: a cluster seeded\n-- from an existing charger re-appended the very ref that matched it, so every\n-- re-ingest of an already-stored area failed while a first ingest of a cold\n-- area succeeded. This adds the database-side guard so no future caller can\n-- reintroduce the failure.\n--\n-- Byte-for-byte 022 apart from the two DISTINCT ON clauses; the signature must\n-- stay `returns int` because create-or-replace cannot change a return type.\n-- =============================================================================\n\ncreate or replace function upsert_chargers_batch(p_chargers jsonb)\nreturns int\nlanguage plpgsql\nsecurity definer\nset search_path = public\nas $$\ndeclare\n  v_row       jsonb;\n  v_id        uuid;\n  v_hash      text;\n  v_old_hash  text;\n  v_count     int := 0;\nbegin\n  for v_row in select * from jsonb_array_elements(p_chargers)\n  loop\n    v_id   := nullif(v_row->>'id', '')::uuid;\n    v_hash := v_row->>'hash';\n\n    if v_id is null then\n      -- INSERT new charger\n      insert into chargers (\n        location, name, operator, operator_id, country, address,\n        max_power_kw, pricing, confidence, availability, source_count,\n        source_hash, last_seen_at, updated_at\n      ) values (\n        ST_SetSRID(ST_MakePoint(\n          (v_row->>'lng')::float8,\n          (v_row->>'lat')::float8\n        ), 4326)::geography,\n        v_row->>'name',\n        v_row->>'operator',\n        v_row->>'operatorId',\n        v_row->>'country',\n        coalesce(v_row->'address', '{}'::jsonb),\n        nullif(v_row->>'maxPowerKw', '')::numeric,\n        v_row->'pricing',\n        coalesce((v_row->>'confidence')::real, 0),\n        coalesce(v_row->>'availability', 'unknown'),\n        coalesce(jsonb_array_length(v_row->'sources'), 0),\n        v_hash,\n        now(),\n        now()\n      )\n      returning id into v_id;\n\n      -- Insert connectors for the new row\n      delete from charger_connectors where charger_id = v_id;\n      insert into charger_connectors (charger_id, type, power_kw, count)\n      select v_id,\n             coalesce(c->>'type', 'other'),\n             nullif(c->>'powerKw', '')::numeric,\n             coalesce((c->>'count')::int, 1)\n      from jsonb_array_elements(coalesce(v_row->'connectors', '[]'::jsonb)) as c;\n\n      -- Insert provenance for the new row\n      insert into charger_sources (charger_id, source, source_ref, raw, last_seen_at)\n      select distinct on (s->>'source', s->>'ref')\n             v_id, s->>'source', s->>'ref', '{}'::jsonb, now()\n      from jsonb_array_elements(coalesce(v_row->'sources', '[]'::jsonb)) as s\n      on conflict (source, source_ref)\n      do update set charger_id = excluded.charger_id, last_seen_at = now();\n\n    else\n      -- Check existing hash\n      select source_hash into v_old_hash from chargers where id = v_id;\n\n      if v_old_hash is not null and v_old_hash = v_hash then\n        -- Hash match: only touch last_seen_at, skip all writes\n        update chargers set last_seen_at = now() where id = v_id;\n      else\n        -- Full update\n        update chargers set\n          location     = ST_SetSRID(ST_MakePoint(\n                           (v_row->>'lng')::float8,\n                           (v_row->>'lat')::float8\n                         ), 4326)::geography,\n          name         = v_row->>'name',\n          operator     = v_row->>'operator',\n          operator_id  = v_row->>'operatorId',\n          country      = v_row->>'country',\n          address      = coalesce(v_row->'address', '{}'::jsonb),\n          max_power_kw = nullif(v_row->>'maxPowerKw', '')::numeric,\n          pricing      = v_row->'pricing',\n          confidence   = coalesce((v_row->>'confidence')::real, 0),\n          availability = coalesce(v_row->>'availability', 'unknown'),\n          source_count = coalesce(jsonb_array_length(v_row->'sources'), 0),\n          source_hash  = v_hash,\n          last_seen_at = now(),\n          updated_at   = now()\n        where id = v_id;\n\n        -- Replace connectors\n        delete from charger_connectors where charger_id = v_id;\n        insert into charger_connectors (charger_id, type, power_kw, count)\n        select v_id,\n               coalesce(c->>'type', 'other'),\n               nullif(c->>'powerKw', '')::numeric,\n               coalesce((c->>'count')::int, 1)\n        from jsonb_array_elements(coalesce(v_row->'connectors', '[]'::jsonb)) as c;\n\n        -- Upsert provenance\n        insert into charger_sources (charger_id, source, source_ref, raw, last_seen_at)\n        select distinct on (s->>'source', s->>'ref')\n               v_id, s->>'source', s->>'ref', '{}'::jsonb, now()\n        from jsonb_array_elements(coalesce(v_row->'sources', '[]'::jsonb)) as s\n        on conflict (source, source_ref)\n        do update set charger_id = excluded.charger_id, last_seen_at = now();\n      end if;\n    end if;\n\n    v_count := v_count + 1;\n  end loop;\n\n  return v_count;\nend;\n$$;\n"
  },
  {
    "id": "038_dedupe_same_site_across_operator_names",
    "description": "Collapse one site stored under several operator names",
    "sql": "-- =============================================================================\n-- 038: collapse one site stored under several operator names.\n--\n-- Reported from the field (Litochoro, GR): a single charge point drawn as three\n-- pins. Each source had attributed it differently — the network on one\n-- (\"PlugQ\"), the fuel station hosting it on another (\"Jet Oil ΚΟΥΤΣΙΜΑΝΗ\") — and\n-- both the runtime dedup and migration 034 keyed on operator equality, so the\n-- rows never met.\n--\n-- src/lib/chargers/dedup.ts now lets hardware agreement override a name\n-- disagreement inside a tight radius. This applies the same rule to rows already\n-- stored, which no amount of re-ingesting would merge on its own: clustering\n-- matches an incoming record against existing ones, it never reconciles two\n-- existing rows with each other.\n--\n-- Deliberately narrower than 034:\n--   * 15 m, not 40 — matching hardware is weak evidence on its own (CCS at\n--     150 kW is a stock configuration), so it only counts within one bank of\n--     stalls, where two different networks do not realistically sit.\n--   * identical max_power_kw required — the stand-in for \"same physical kit\"\n--     available in SQL.\n--\n-- Rows sharing an operator are already handled by 034 and are left alone here.\n-- Survivor selection matches 034: highest confidence, then most sources, then\n-- greatest id — a total order, so exactly one row of any pair remains.\n--\n-- Idempotent: re-running is a no-op once each site holds a single row.\n-- =============================================================================\n\ncreate or replace function public.dedupe_same_site_names(p_limit integer default 2000)\nreturns integer\nlanguage plpgsql\nsecurity definer\nset search_path = public\nas $$\ndeclare\n  v_deleted integer;\nbegin\n  delete from chargers\n  where id in (\n    select c.id\n    from chargers c\n    where exists (\n      select 1\n      from chargers k\n      where k.id <> c.id\n        and st_dwithin(c.location, k.location, 15)\n        -- Same rated power stands in for \"same physical hardware\".\n        and k.max_power_kw is not null\n        and c.max_power_kw is not null\n        and round(k.max_power_kw) = round(c.max_power_kw)\n        -- Equal-operator pairs are 034's job; this pass exists for the rows it\n        -- cannot see, so restricting to differing names keeps the two disjoint.\n        and coalesce(k.operator_id, '~unknown') <> coalesce(c.operator_id, '~unknown')\n        and (k.confidence, k.source_count, k.id) > (c.confidence, c.source_count, c.id)\n    )\n    limit p_limit\n  );\n\n  get diagnostics v_deleted = row_count;\n  return v_deleted;\nend;\n$$;\n\n-- Run repeatedly until it reports 0.\n--   select public.dedupe_same_site_names(2000);\n"
  },
  {
    "id": "039_dedupe_same_site_brand",
    "description": "Collapse one site whose brand is split across name and operator",
    "sql": "-- =============================================================================\n-- 039: collapse one site whose brand is split across the name and operator\n-- fields.\n--\n-- Reported from the field (Nea Kerdilia, GR): one Shell forecourt drawn as two\n-- pins. OCM holds it twice with the brand in opposite fields:\n--\n--   name: 'SHELL Nea Kerdilia'  operator: 'NRGincharge'\n--   name: 'nrg - Shell'         operator: 'Shell ΠΑΡΑΣΚΕΥΟΠΟΥΛΟΣ'\n--\n-- Operator-to-operator comparison is what both the runtime dedup and every\n-- earlier migration key on, and it reads ~0.09 here: the Greek host name\n-- reduces to 'shell', nothing like 'nrgincharge'. So the pair looked like two\n-- networks. Both records name Shell — only the field differs.\n--\n-- src/lib/chargers/dedup.ts now retracts the operator conflict when one row's\n-- declared operator appears anywhere in the other's name or operator, provided\n-- the hardware agrees. This applies the same rule to rows already stored, which\n-- re-ingesting cannot fix on its own: clustering matches an incoming record\n-- against existing ones, it never reconciles two existing rows with each other.\n--\n-- Relation to the earlier passes, kept disjoint so they compose:\n--   * 034 merges rows that AGREE on operator, within 40 m.\n--   * 038 merges rows that DISAGREE, within 15 m, on hardware agreement alone.\n--   * 039 (this) merges rows that disagree within 40 m, but only when they\n--     share a brand token — a stronger signal than 038's, which is why it is\n--     allowed the wider radius.\n--\n-- Survivor selection matches 034 and 038: highest confidence, then most\n-- sources, then greatest id — a total order, so exactly one row of any pair\n-- remains.\n--\n-- Idempotent: re-running is a no-op once each site holds a single row.\n-- =============================================================================\n\n-- Brand-ish tokens of a text field: lowercase, split on anything that is not\n-- [a-z0-9], keep tokens of 5+ characters, drop the ones that describe a charger\n-- rather than name a business.\n--\n-- Mirrors brandTokens() in src/lib/chargers/dedup.ts, including the 5-char\n-- floor (a short generic fragment is not a brand, while Shell/Tesla/Enel/PlugQ\n-- reach 5) and the stoplist (length alone cannot filter 'charging' or\n-- 'station', both longer than 'shell'). Non-Latin scripts fall out here exactly\n-- as they do in the TypeScript: Greek and Cyrillic are not [a-z0-9] and so act\n-- as separators, which is why a Greek-only operator yields no tokens and can\n-- never be merged on this rule.\ncreate or replace function public.charger_brand_tokens(p_text text)\nreturns text[]\nlanguage sql\nimmutable\nparallel safe\nas $$\n  select coalesce(array_agg(distinct t), '{}'::text[])\n  from unnest(\n    regexp_split_to_array(lower(coalesce(p_text, '')), '[^a-z0-9]+')\n  ) as t\n  where length(t) >= 5\n    and t <> all (array[\n      'charge', 'charger', 'chargers', 'charging', 'chargepoint',\n      'station', 'stations', 'point', 'points', 'plug', 'socket', 'outlet',\n      'power', 'energy', 'electric', 'electrical', 'mobility', 'emobility',\n      'public', 'private', 'parking', 'garage', 'hotel', 'restaurant',\n      'market', 'supermarket', 'center', 'centre', 'centrum', 'plaza',\n      'mall', 'store', 'petrol', 'fuel', 'service', 'services', 'motorway',\n      'highway', 'north', 'south', 'east', 'west', 'rapid', 'fast', 'ultra',\n      'super', 'recharge', 'network', 'group', 'limited', 'gmbh', 'srl',\n      'sa', 'bv', 'ltd'\n    ]);\n$$;\n\ncreate or replace function public.dedupe_same_site_brand(p_limit integer default 2000)\nreturns integer\nlanguage plpgsql\nsecurity definer\nset search_path = public\nas $$\ndeclare\n  v_deleted integer;\nbegin\n  delete from chargers\n  where id in (\n    select c.id\n    from chargers c\n    where exists (\n      select 1\n      from chargers k\n      where k.id <> c.id\n        and st_dwithin(c.location, k.location, 40)\n        -- Same rated power stands in for \"same physical hardware\" — the\n        -- corroboration the TypeScript rule requires alongside the brand match,\n        -- so a 350 kW Ionity bay on a Shell forecourt is not absorbed by the\n        -- host's 60 kW one.\n        and k.max_power_kw is not null\n        and c.max_power_kw is not null\n        and round(k.max_power_kw) = round(c.max_power_kw)\n        -- Equal-operator pairs are 034's job; restricting to differing names\n        -- keeps the passes disjoint.\n        and coalesce(k.operator_id, '~unknown') <> coalesce(c.operator_id, '~unknown')\n        -- One row's declared OPERATOR appears in the other's name or operator.\n        -- Deliberately not a name-to-name overlap: two unrelated stations in one\n        -- village both carry the village in their name, and merging on that\n        -- would collapse genuinely separate sites. Requiring the shared token to\n        -- be somebody's operator makes it a claim about the network.\n        and (\n          public.charger_brand_tokens(k.operator)\n            && public.charger_brand_tokens(concat_ws(' ', c.name, c.operator))\n          or public.charger_brand_tokens(c.operator)\n            && public.charger_brand_tokens(concat_ws(' ', k.name, k.operator))\n        )\n        and (k.confidence, k.source_count, k.id) > (c.confidence, c.source_count, c.id)\n    )\n    limit p_limit\n  );\n\n  get diagnostics v_deleted = row_count;\n  return v_deleted;\nend;\n$$;\n\n-- Run repeatedly until it reports 0.\n--   select public.dedupe_same_site_brand(2000);\n"
  },
  {
    "id": "040_saved_routes_unique",
    "description": "One saved route per origin/destination pair (removes existing duplicates)",
    "sql": "-- =============================================================================\n-- 040: one saved route per origin/destination pair, per user.\n--\n-- Reported from the field: the same route saved twice. Two ways in, and the\n-- client-side guard only ever closed the first:\n--\n--   * Double tap. `routeSaved` is set after the POST resolves, so on a slow\n--     mobile connection two taps inside the round-trip both saw it false and\n--     both inserted. Three of the four save buttons also lacked the in-flight\n--     disable that the fourth had.\n--   * Saving the same trip again — a retry after a flaky response, a second\n--     tab, or loading a saved route and pressing save. No client guard can see\n--     any of these; only the database can.\n--\n-- route_key is GENERATED, so the value cannot drift from the row it describes\n-- and no application code can forget to set it. Coordinates are rounded to 4\n-- decimals (~11 m) so re-geocoding the same place lands on the same key,\n-- while two genuinely different addresses do not collide.\n--\n-- Deliberately keyed on origin+destination only, NOT the stops: re-planning\n-- A→B picks different chargers as the SoC or the filters change, and storing\n-- that as a second route is exactly the duplicate being reported. The list is\n-- capped at 10 and reads as \"my routes\", so re-saving A→B should refresh the\n-- stored plan rather than add a row — which is what the API now does.\n-- =============================================================================\n\n-- Defined once and used by both the generated column and the API, so the two\n-- can never disagree about what \"the same route\" means. The API calls it as an\n-- RPC to learn a payload's key before deciding whether a save is a new route\n-- (which counts against the 10-route cap) or a refresh of an existing one\n-- (which must not).\ncreate or replace function public.saved_route_key(\n  p_origin_lat float8, p_origin_lng float8,\n  p_destination_lat float8, p_destination_lng float8\n)\nreturns text\nlanguage sql\nimmutable\nparallel safe\nas $$\n  select md5(\n    round(p_origin_lat::numeric, 4)::text || ',' ||\n    round(p_origin_lng::numeric, 4)::text || ';' ||\n    round(p_destination_lat::numeric, 4)::text || ',' ||\n    round(p_destination_lng::numeric, 4)::text\n  );\n$$;\n\nalter table public.saved_routes\n  add column if not exists route_key text generated always as (\n    public.saved_route_key(origin_lat, origin_lng, destination_lat, destination_lng)\n  ) stored;\n\n-- Existing duplicates must go before the unique index can be built. Keep the\n-- most recent of each group: it carries the freshest plan snapshot, and the\n-- older row is the accident.\ndelete from public.saved_routes a\nusing public.saved_routes b\nwhere a.user_id = b.user_id\n  and a.route_key = b.route_key\n  and (a.created_at, a.id) < (b.created_at, b.id);\n\ncreate unique index if not exists saved_routes_user_route_key_uidx\n  on public.saved_routes(user_id, route_key);\n"
  },
  {
    "id": "041_dedupe_use_spatial_index",
    "description": "Fix the dedupe statement timeout (381s -> 0.2s); apply before running dedupe",
    "sql": "-- =============================================================================\n-- 041: make every dedupe pass use the spatial index.\n--\n-- Reported from the field: \"Dedupe failed: canceling statement due to statement\n-- timeout\". Measured on a 22,253-row copy of the live table:\n--\n--   dedupe_chargers_batch    (034)   57 s\n--   dedupe_same_site_names   (038)   36 s\n--   dedupe_same_site_brand   (039)  381 s\n--\n-- All three exceed the statement timeout, so the panel's dedupe button could\n-- never finish. 039 made it obvious, but 034 timing out is the same failure the\n-- Litochoro work already hit once (\"034 pică cu upstream timeout\") and it was\n-- never actually fixed — only worked around by shrinking the batch.\n--\n-- Cause, shared by all three: each carries an equality predicate — operator_id\n-- for 034, round(max_power_kw) for 038/039 — and the planner would rather hash\n-- join on it than use the GiST index. EXPLAIN showed\n--\n--   Hash Semi Join  (Hash Cond: round(c.max_power_kw) = round(k.max_power_kw))\n--     Join Filter: ... st_dwithin(c.location, k.location, 40)\n--     -> Seq Scan on chargers c\n--     -> Hash -> Seq Scan on chargers k\n--\n-- so chargers_geo_gix (migration 017) went unused and st_dwithin — plus, in\n-- 039, four charger_brand_tokens() calls — ran on every pair sharing a rated\n-- power. With a few dozen distinct power values over 22k rows, that is tens of\n-- millions of pairs.\n--\n-- Fix, in two parts:\n--\n--   1. CROSS JOIN LATERAL (... LIMIT 1) instead of a correlated EXISTS. The\n--      LIMIT makes the subquery non-flattenable, so the planner cannot hoist it\n--      into a hash join and settles on the nested loop the data wants:\n--\n--        Nested Loop\n--          -> Seq Scan on chargers c\n--          -> Limit -> Index Scan using chargers_geo_gix on chargers k\n--                        Index Cond: location && _st_expand(c.location, 40)\n--\n--      Semantically identical: EXISTS and a LATERAL that stops at the first\n--      match both ask \"is there any such neighbour\".\n--\n--   2. Precompute the brand token arrays as generated columns, so 039 stops\n--      calling charger_brand_tokens() once per candidate pair.\n--\n-- Result on the same 22,253 rows: 381 s -> 229 ms for 039.\n--\n-- Adding the generated columns rewrites the table and takes an ACCESS EXCLUSIVE\n-- lock. At this size that is seconds; on a much larger table it would need a\n-- maintenance window.\n-- =============================================================================\n\n-- coalesce/|| rather than concat_ws: concat_ws is only STABLE (it goes through\n-- type output functions), and a generated column requires IMMUTABLE.\nalter table public.chargers\n  add column if not exists operator_brand text[]\n    generated always as (public.charger_brand_tokens(operator)) stored;\n\nalter table public.chargers\n  add column if not exists site_brand text[]\n    generated always as (\n      public.charger_brand_tokens(coalesce(name, '') || ' ' || coalesce(operator, ''))\n    ) stored;\n\n-- NOTE: these columns depend on charger_brand_tokens(). Replacing that function\n-- later will NOT recompute the stored values — the columns would have to be\n-- dropped and re-added, or the table rewritten with a no-op ALTER.\n\n-- --------------------------------------------------------------------------\n-- 034's rule: same operator, within 40 m.\n-- --------------------------------------------------------------------------\ncreate or replace function public.dedupe_chargers_batch(p_limit integer default 2000)\nreturns integer\nlanguage plpgsql\nsecurity definer\nset search_path = public\nas $$\ndeclare\n  v_deleted integer;\nbegin\n  delete from chargers\n  where id in (\n    select c.id\n    from chargers c\n    cross join lateral (\n      select 1\n      from chargers k\n      where st_dwithin(c.location, k.location, 40)\n        and k.id <> c.id\n        and coalesce(k.operator_id, '~unknown') = coalesce(c.operator_id, '~unknown')\n        and (k.confidence, k.source_count, k.id) > (c.confidence, c.source_count, c.id)\n      limit 1\n    ) hit\n    limit p_limit\n  );\n\n  get diagnostics v_deleted = row_count;\n  return v_deleted;\nend;\n$$;\n\n-- --------------------------------------------------------------------------\n-- 034's per-country variant. Same rewrite; the country branch is kept because\n-- `is not distinct from` has no btree operator class and forces a seq scan.\n-- --------------------------------------------------------------------------\ncreate or replace function public.dedupe_chargers_by_site(\n  p_country char(2),\n  p_limit   integer default 200000\n)\nreturns integer\nlanguage plpgsql\nsecurity definer\nset search_path = public\nas $$\ndeclare\n  v_deleted integer;\nbegin\n  if p_country is null then\n    delete from chargers\n    where id in (\n      select c.id\n      from chargers c\n      cross join lateral (\n        select 1\n        from chargers k\n        where st_dwithin(c.location, k.location, 40)\n          and k.id <> c.id\n          and coalesce(k.operator_id, '~unknown') = coalesce(c.operator_id, '~unknown')\n          and (k.confidence, k.source_count, k.id) > (c.confidence, c.source_count, c.id)\n        limit 1\n      ) hit\n      where c.country is null\n      limit p_limit\n    );\n  else\n    delete from chargers\n    where id in (\n      select c.id\n      from chargers c\n      cross join lateral (\n        select 1\n        from chargers k\n        where st_dwithin(c.location, k.location, 40)\n          and k.id <> c.id\n          and coalesce(k.operator_id, '~unknown') = coalesce(c.operator_id, '~unknown')\n          and (k.confidence, k.source_count, k.id) > (c.confidence, c.source_count, c.id)\n        limit 1\n      ) hit\n      where c.country = p_country\n      limit p_limit\n    );\n  end if;\n\n  get diagnostics v_deleted = row_count;\n  return v_deleted;\nend;\n$$;\n\n-- --------------------------------------------------------------------------\n-- 038's rule: differing operators, same rated power, within one bay (15 m).\n-- --------------------------------------------------------------------------\ncreate or replace function public.dedupe_same_site_names(p_limit integer default 2000)\nreturns integer\nlanguage plpgsql\nsecurity definer\nset search_path = public\nas $$\ndeclare\n  v_deleted integer;\nbegin\n  delete from chargers\n  where id in (\n    select c.id\n    from chargers c\n    cross join lateral (\n      select 1\n      from chargers k\n      where st_dwithin(c.location, k.location, 15)\n        and k.id <> c.id\n        and k.max_power_kw is not null\n        and round(k.max_power_kw) = round(c.max_power_kw)\n        and coalesce(k.operator_id, '~unknown') <> coalesce(c.operator_id, '~unknown')\n        and (k.confidence, k.source_count, k.id) > (c.confidence, c.source_count, c.id)\n      limit 1\n    ) hit\n    where c.max_power_kw is not null\n    limit p_limit\n  );\n\n  get diagnostics v_deleted = row_count;\n  return v_deleted;\nend;\n$$;\n\n-- --------------------------------------------------------------------------\n-- 039's rule: differing operators sharing a brand across name/operator, same\n-- rated power, within 40 m. Now reads the precomputed arrays.\n-- --------------------------------------------------------------------------\ncreate or replace function public.dedupe_same_site_brand(p_limit integer default 2000)\nreturns integer\nlanguage plpgsql\nsecurity definer\nset search_path = public\nas $$\ndeclare\n  v_deleted integer;\nbegin\n  delete from chargers\n  where id in (\n    select c.id\n    from chargers c\n    cross join lateral (\n      select 1\n      from chargers k\n      where st_dwithin(c.location, k.location, 40)\n        and k.id <> c.id\n        and k.max_power_kw is not null\n        and round(k.max_power_kw) = round(c.max_power_kw)\n        and coalesce(k.operator_id, '~unknown') <> coalesce(c.operator_id, '~unknown')\n        and (k.operator_brand && c.site_brand or c.operator_brand && k.site_brand)\n        and (k.confidence, k.source_count, k.id) > (c.confidence, c.source_count, c.id)\n      limit 1\n    ) hit\n    where c.max_power_kw is not null\n    limit p_limit\n  );\n\n  get diagnostics v_deleted = row_count;\n  return v_deleted;\nend;\n$$;\n"
  },
  {
    "id": "042_charger_sources_fk_index",
    "description": "Index the charger_sources foreign key (cascade delete 1716ms -> 25ms)",
    "sql": "-- =============================================================================\n-- 042: index charger_sources.charger_id.\n--\n-- charger_sources references chargers(id) ON DELETE CASCADE but migration 017\n-- only ever indexed (source, source_ref) — the uniqueness constraint — never\n-- the foreign key column. charger_connectors got its index (cc_charger); this\n-- table was missed.\n--\n-- Postgres does not index a referencing column for you, so every cascade fired\n-- a sequential scan of charger_sources to find the rows to remove. Deleting a\n-- 2,000-row dedupe batch against ~20k source rows measured:\n--\n--   without the index   1,716 ms\n--   with the index         25 ms\n--\n-- That cost rode on top of every dedupe pass, and on any other charger delete.\n-- It is not the whole of the timeout that was reported — that was 041's planner\n-- problem, compounded by re-applying 038 after 041 and reverting one of its\n-- functions — but it is the part that would have kept the passes slow once\n-- there were duplicates to actually remove. The earlier benchmark deleted no\n-- rows, so it never exercised the cascade at all.\n-- =============================================================================\n\ncreate index if not exists charger_sources_charger_id_idx\n  on public.charger_sources(charger_id);\n"
  },
  {
    "id": "043_dedupe_keeps_provenance",
    "description": "Dedupe transfers source refs to the survivor; recompute source_count",
    "sql": "-- =============================================================================\n-- 043: dedupe transfers provenance instead of discarding it, and source_count\n-- is recomputed from the rows that actually exist.\n--\n-- Two related problems, both visible in the debug panel as chargers outnumbering\n-- charger_sources rows (6,300 orphans before the first big dedupe, 1,160 after).\n--\n-- 1. Deleting a duplicate cascades its charger_sources rows away. The surviving\n--    charger never learns a second source corroborated it, so confidence — which\n--    is computed from the source count — stays lower than the evidence warrants.\n--    Migration 034 noted that re-ingest re-attaches the freed refs, which is\n--    true, but it only happens when that area is fetched again.\n--\n-- 2. source_count is written by upsert_chargers_batch from the payload\n--    (jsonb_array_length of the cluster's sources), never counted from the\n--    table. So it drifts from reality and nothing reveals it — which is why the\n--    orphans were invisible until the totals were compared by hand.\n--\n-- The transfer picks the best neighbour, ordered exactly like the survivor rule\n-- (confidence, source_count, id). In a chain longer than the merge radius that\n-- neighbour can itself be deleted in the same pass, and those refs still\n-- cascade; the panel loops until no duplicates remain, and re-ingest recovers\n-- the rest. Strictly better than discarding every deleted row's provenance,\n-- without pretending to be exhaustive.\n--\n-- charger_sources is unique on (source, source_ref) globally, so a ref can be\n-- repointed without any chance of colliding with one the survivor already has.\n-- =============================================================================\n\n-- One-off repair: make source_count agree with the table.\nupdate public.chargers c\nset source_count = coalesce(s.n, 0)\nfrom (\n  select ch.id, count(cs.id) as n\n  from public.chargers ch\n  left join public.charger_sources cs on cs.charger_id = ch.id\n  group by ch.id\n) s\nwhere s.id = c.id\n  and c.source_count is distinct from coalesce(s.n, 0);\n\n-- --------------------------------------------------------------------------\n-- Same operator, within 40 m (034's rule).\n-- --------------------------------------------------------------------------\ncreate or replace function public.dedupe_chargers_batch(p_limit integer default 2000)\nreturns integer\nlanguage plpgsql\nsecurity definer\nset search_path = public\nas $$\ndeclare\n  v_deleted integer;\nbegin\n  create temporary table if not exists _dedupe_pairs (dup_id uuid, keep_id uuid)\n    on commit drop;\n  truncate _dedupe_pairs;\n\n  insert into _dedupe_pairs (dup_id, keep_id)\n  select c.id, best.id\n  from chargers c\n  cross join lateral (\n    select k.id\n    from chargers k\n    where st_dwithin(c.location, k.location, 40)\n      and k.id <> c.id\n      and coalesce(k.operator_id, '~unknown') = coalesce(c.operator_id, '~unknown')\n      and (k.confidence, k.source_count, k.id) > (c.confidence, c.source_count, c.id)\n    order by k.confidence desc, k.source_count desc, k.id desc\n    limit 1\n  ) best\n  limit p_limit;\n\n  update charger_sources s\n  set charger_id = p.keep_id\n  from _dedupe_pairs p\n  where s.charger_id = p.dup_id\n    and not exists (select 1 from _dedupe_pairs d where d.dup_id = p.keep_id);\n\n  delete from chargers where id in (select dup_id from _dedupe_pairs);\n  get diagnostics v_deleted = row_count;\n\n  update chargers c\n  set source_count = (select count(*) from charger_sources cs where cs.charger_id = c.id)\n  where c.id in (select keep_id from _dedupe_pairs);\n\n  return v_deleted;\nend;\n$$;\n\n-- --------------------------------------------------------------------------\n-- Differing operators, same rated power, within one bay (038's rule).\n-- --------------------------------------------------------------------------\ncreate or replace function public.dedupe_same_site_names(p_limit integer default 2000)\nreturns integer\nlanguage plpgsql\nsecurity definer\nset search_path = public\nas $$\ndeclare\n  v_deleted integer;\nbegin\n  create temporary table if not exists _dedupe_pairs (dup_id uuid, keep_id uuid)\n    on commit drop;\n  truncate _dedupe_pairs;\n\n  insert into _dedupe_pairs (dup_id, keep_id)\n  select c.id, best.id\n  from chargers c\n  cross join lateral (\n    select k.id\n    from chargers k\n    where st_dwithin(c.location, k.location, 15)\n      and k.id <> c.id\n      and k.max_power_kw is not null\n      and round(k.max_power_kw) = round(c.max_power_kw)\n      and coalesce(k.operator_id, '~unknown') <> coalesce(c.operator_id, '~unknown')\n      and (k.confidence, k.source_count, k.id) > (c.confidence, c.source_count, c.id)\n    order by k.confidence desc, k.source_count desc, k.id desc\n    limit 1\n  ) best\n  where c.max_power_kw is not null\n  limit p_limit;\n\n  update charger_sources s\n  set charger_id = p.keep_id\n  from _dedupe_pairs p\n  where s.charger_id = p.dup_id\n    and not exists (select 1 from _dedupe_pairs d where d.dup_id = p.keep_id);\n\n  delete from chargers where id in (select dup_id from _dedupe_pairs);\n  get diagnostics v_deleted = row_count;\n\n  update chargers c\n  set source_count = (select count(*) from charger_sources cs where cs.charger_id = c.id)\n  where c.id in (select keep_id from _dedupe_pairs);\n\n  return v_deleted;\nend;\n$$;\n\n-- --------------------------------------------------------------------------\n-- Brand split across name and operator, within 40 m (039's rule).\n-- --------------------------------------------------------------------------\ncreate or replace function public.dedupe_same_site_brand(p_limit integer default 2000)\nreturns integer\nlanguage plpgsql\nsecurity definer\nset search_path = public\nas $$\ndeclare\n  v_deleted integer;\nbegin\n  create temporary table if not exists _dedupe_pairs (dup_id uuid, keep_id uuid)\n    on commit drop;\n  truncate _dedupe_pairs;\n\n  insert into _dedupe_pairs (dup_id, keep_id)\n  select c.id, best.id\n  from chargers c\n  cross join lateral (\n    select k.id\n    from chargers k\n    where st_dwithin(c.location, k.location, 40)\n      and k.id <> c.id\n      and k.max_power_kw is not null\n      and round(k.max_power_kw) = round(c.max_power_kw)\n      and coalesce(k.operator_id, '~unknown') <> coalesce(c.operator_id, '~unknown')\n      and (k.operator_brand && c.site_brand or c.operator_brand && k.site_brand)\n      and (k.confidence, k.source_count, k.id) > (c.confidence, c.source_count, c.id)\n    order by k.confidence desc, k.source_count desc, k.id desc\n    limit 1\n  ) best\n  where c.max_power_kw is not null\n  limit p_limit;\n\n  update charger_sources s\n  set charger_id = p.keep_id\n  from _dedupe_pairs p\n  where s.charger_id = p.dup_id\n    and not exists (select 1 from _dedupe_pairs d where d.dup_id = p.keep_id);\n\n  delete from chargers where id in (select dup_id from _dedupe_pairs);\n  get diagnostics v_deleted = row_count;\n\n  update chargers c\n  set source_count = (select count(*) from charger_sources cs where cs.charger_id = c.id)\n  where c.id in (select keep_id from _dedupe_pairs);\n\n  return v_deleted;\nend;\n$$;\n"
  },
  {
    "id": "044_charger_query_limits",
    "description": "Stop silently dropping stations from map queries (500 cap -> 2000)",
    "sql": "-- =============================================================================\n-- 044: stop silently dropping stations from a viewport query.\n--\n-- Reported from the field: stations show on the map, vanish when you zoom in,\n-- and come back when you zoom out.\n--\n-- Four layers disagreed about the limit and nothing reconciled them:\n--\n--   src/lib/api/chargers.ts      asks for 2000\n--   src/app/api/chargers/route.ts  schema allows up to 2000\n--   src/lib/chargers/query.ts    MAX_LIMIT 5000, DEFAULT_LIMIT 1000\n--   this function                least(coalesce(p_limit, 200), 500)   <-- wins\n--\n-- So every caller's limit was quietly cut to 500, and because the ordering is\n-- `confidence desc`, the 500 kept were the highest-confidence ones — which are\n-- spread over the whole bbox, not the part being looked at.\n--\n-- Reproduced on a local PostGIS with 601 stations in northern Greece and one\n-- target at confidence 0.30:\n--\n--   wide bbox   -> target_found = 0, total = 500   (silently dropped)\n--   tight bbox  -> target_found = 1, total = 1     (correct)\n--\n-- Raising the cap to 2000 matches the contract the API already advertises. It\n-- does not make truncation impossible — a continent-wide bbox can still exceed\n-- it — but it moves the ceiling above any realistic viewport, and the client\n-- already asks for exactly this number.\n--\n-- Ordering is left as confidence desc: when something must be dropped, the\n-- least-trustworthy rows are the right ones to lose. The remaining flaw is that\n-- truncation is invisible to the caller, which is recorded in docs/TODO.md\n-- rather than papered over here — the response is a bare array with nowhere to\n-- report it.\n-- =============================================================================\n\ncreate or replace function chargers_in_bbox(\n  p_min_lng        float8,\n  p_min_lat        float8,\n  p_max_lng        float8,\n  p_max_lat        float8,\n  p_min_kw         float8 default null,\n  p_connector      text   default null,\n  p_min_confidence real   default 0,\n  p_limit          int    default 1000\n)\nreturns table (\n  id           uuid,\n  lat          float8,\n  lng          float8,\n  name         text,\n  operator     text,\n  operator_id  text,\n  country      char(2),\n  address      jsonb,\n  max_power_kw numeric,\n  pricing      jsonb,\n  availability text,\n  confidence   real,\n  last_seen_at timestamptz,\n  connectors   jsonb,\n  sources      jsonb\n)\nlanguage sql\nstable\nsecurity definer\nset search_path = public\nas $$\n  select\n    ch.id,\n    st_y(ch.location::geometry) as lat,\n    st_x(ch.location::geometry) as lng,\n    ch.name,\n    ch.operator,\n    ch.operator_id,\n    ch.country,\n    ch.address,\n    ch.max_power_kw,\n    ch.pricing,\n    ch.availability,\n    ch.confidence,\n    ch.last_seen_at,\n    coalesce(\n      (select jsonb_agg(jsonb_build_object('type', c.type, 'powerKw', c.power_kw, 'count', c.count))\n         from charger_connectors c where c.charger_id = ch.id),\n      '[]'::jsonb\n    ) as connectors,\n    coalesce(\n      (select jsonb_agg(jsonb_build_object('source', s.source, 'ref', s.source_ref))\n         from charger_sources s where s.charger_id = ch.id),\n      '[]'::jsonb\n    ) as sources\n  from chargers ch\n  where st_intersects(\n          ch.location,\n          st_makeenvelope(p_min_lng, p_min_lat, p_max_lng, p_max_lat, 4326)::geography\n        )\n    and (p_min_kw is null or ch.max_power_kw >= p_min_kw)\n    and ch.confidence >= coalesce(p_min_confidence, 0)\n    and (\n      p_connector is null\n      or exists (\n        select 1 from charger_connectors c\n        where c.charger_id = ch.id and c.type = p_connector\n      )\n    )\n  -- id as a tiebreak so a truncated page is at least stable between identical\n  -- requests; confidence alone leaves ties in arbitrary order, which made the\n  -- same viewport return different stations on consecutive fetches.\n  order by ch.confidence desc, ch.id\n  limit greatest(1, least(coalesce(p_limit, 1000), 2000));\n$$;\n"
  },
  {
    "id": "045_push_subscription_ownership",
    "description": "Push endpoints are owned per user — posting someone else's no longer steals their row",
    "sql": "-- 045_push_subscription_ownership.sql\n--\n-- A push endpoint was globally unique, and /api/push/subscribe upserted with\n-- onConflict: \"endpoint\". Posting an endpoint that already belonged to someone\n-- else therefore rewrote that row's user_id: the victim silently lost their\n-- subscription and the attacker's notifications were delivered to the victim's\n-- browser.\n--\n-- The conflict target becomes (user_id, endpoint), so a repeat subscribe still\n-- updates your own row and a foreign endpoint can only ever create a row of\n-- your own. It cannot take one over.\n--\n-- Duplicates are removed first, newest kept, or the new unique index cannot be\n-- built. There should be none — the old constraint made them impossible — but\n-- this must be safe to run twice.\n\ndelete from public.push_subscriptions a\nusing public.push_subscriptions b\nwhere a.user_id = b.user_id\n  and a.endpoint = b.endpoint\n  and a.ctid < b.ctid;\n\nalter table public.push_subscriptions\n  drop constraint if exists push_subscriptions_endpoint_key;\n\ncreate unique index if not exists push_subscriptions_user_endpoint_key\n  on public.push_subscriptions (user_id, endpoint);\n"
  },
  {
    "id": "046_email_verification",
    "description": "profiles.email_verified_at — needs RESEND_API_KEY set, or document recovery locks for everyone",
    "sql": "-- 046_email_verification.sql\n--\n-- Proof that a user controls the address they registered with.\n--\n-- /api/auth/register calls createUser with email_confirm: true and sends no\n-- verification mail, because login goes through signInWithPassword and Supabase\n-- refuses an unconfirmed address. So auth.users.email_confirmed_at is set for\n-- everyone the moment they register and proves nothing.\n--\n-- That mattered because /api/documents/recover treats the address as identity:\n-- it hands over every unmatched inbound document whose sender_email matches.\n-- Register someone else's address — which nothing prevented — and their\n-- documents were claimable. Gating on Supabase's own confirmed_at would have\n-- looked like a fix and changed nothing, since it is always set.\n--\n-- This column is ours, defaults to null, and is only ever written by\n-- /api/account/verify-email after a signed link is opened from the inbox.\n\nalter table public.profiles\n  add column if not exists email_verified_at timestamptz;\n\ncomment on column public.profiles.email_verified_at is\n  'Set when the user opened a signed verification link sent to this address. '\n  'NOT the same as auth.users.email_confirmed_at, which registration forces.';\n"
  },
  {
    "id": "047_revoke_function_execute_from_anon",
    "description": "Revoke function EXECUTE from anon/authenticated (read its header first)",
    "sql": "-- 047_revoke_function_execute_from_anon.sql\n--\n-- Close the RLS bypass that PostgREST leaves open on SECURITY DEFINER functions.\n--\n-- Migration 031 enabled row level security on the charger tables. It did not\n-- help: roughly twenty functions across 018–044 are SECURITY DEFINER, they run\n-- as their owner, and PostgREST exposes every function the caller has EXECUTE\n-- on at POST /rest/v1/rpc/<name>. EXECUTE defaults to PUBLIC, so anyone holding\n-- the anon key — which ships in the browser bundle by design — could call\n-- chargers_in_bbox, upsert_charger, upsert_chargers_batch, the dedupe family\n-- and the debug stats functions directly, with the owner's privileges and RLS\n-- not consulted. Two of them mutate the charger tables.\n--\n-- 035 and 037 already did this per-function for the debug helpers and exec_sql\n-- (which executes arbitrary SQL — that one was correctly locked from the\n-- start). This applies the same rule to the whole schema instead of listing\n-- twenty signatures, which is both shorter and impossible to leave a gap in.\n--\n-- SAFE HERE, and the reason is specific rather than general: no application\n-- code uses the anon or authenticated roles. Every database access goes through\n-- a Next.js route holding the service-role key, and service_role is exempt from\n-- the revoke below. src/lib/supabase/client.ts (createBrowserClient) exists but\n-- is imported by nothing — verified by grep across src/ — and no client\n-- component calls .rpc() anywhere.\n--\n-- IF THAT CHANGES: a function you deliberately want callable from the browser\n-- needs an explicit `grant execute on function <name>(<args>) to anon;` after\n-- this migration. Adding one is a decision; having twenty by default was not.\n\nrevoke execute on all functions in schema public from anon, authenticated;\n\n-- New functions default to PUBLIC too, so without this the gap reopens with the\n-- next migration that adds one. Applies to functions created by the role that\n-- runs this statement, which is the role every migration here runs as.\nalter default privileges in schema public\n  revoke execute on functions from anon, authenticated;\n\n-- Belt and braces: the server holds this role, and it must keep working.\ngrant execute on all functions in schema public to service_role;\n\nalter default privileges in schema public\n  grant execute on functions to service_role;\n"
  },
  {
    "id": "048_enable_rls_everywhere",
    "description": "RLS sweep + the reporting functions the Row-level security tile reads",
    "sql": "-- 048_enable_rls_everywhere.sql\n--\n-- Answers the Supabase advisor's `rls_disabled_in_public` alert, keeps\n-- answering it, and — the part that matters — reports what it found somewhere\n-- a phone can read.\n--\n-- Every table created by a migration in this repo already has RLS enabled,\n-- checked one by one. Whatever the advisor flagged was created by hand in the\n-- SQL editor or belongs to an extension. Confirmed 2026-08-09: one row,\n-- `public.spatial_ref_sys`, owner supabase_admin — PostGIS's EPSG projection\n-- table, no user data, brought in because 017 installs the extension without\n-- `with schema`.\n--\n-- Written as FUNCTIONS rather than a DO block on purpose. The debug panel\n-- applies migrations through `exec_sql`, which returns void, so a DO block's\n-- RAISE NOTICE output goes nowhere — from a phone the migration would succeed\n-- and say nothing, which is the same as not knowing. These return rows, so\n-- /debug can show them and re-show them later.\n--\n-- The sweep enables RLS WITH NO POLICIES, deliberately: that is the model the\n-- rest of the schema uses for shared tables (031, 037). The service-role key\n-- bypasses RLS and every database access in the app holds it, while `anon` and\n-- `authenticated` are reduced to nothing. Neither role is used anywhere —\n-- src/lib/supabase/client.ts is imported by nothing and no component calls\n-- .rpc() — so this cannot break a read path. A table that genuinely needs\n-- browser access needs a policy written for it on purpose.\n\n-- ---------------------------------------------------------------------------\n-- What is exposed, right now.\n-- ---------------------------------------------------------------------------\ncreate or replace function public.debug_rls_status()\nreturns table (\n  table_name text,\n  rls_enabled boolean,\n  owner text,\n  owned_by_extension boolean\n)\nlanguage sql\nsecurity definer\nset search_path = public\nas $$\n  select\n    c.relname::text,\n    c.relrowsecurity,\n    pg_catalog.pg_get_userbyid(c.relowner)::text,\n    exists (\n      select 1 from pg_depend d where d.objid = c.oid and d.deptype = 'e'\n    )\n  from pg_class c\n  join pg_namespace n on n.oid = c.relnamespace\n  where n.nspname = 'public'\n    and c.relkind = 'r'\n  order by c.relrowsecurity, c.relname;\n$$;\n\n-- ---------------------------------------------------------------------------\n-- Who can touch a given table, regardless of RLS.\n--\n-- RLS is not the only gate: a role also needs table privileges. This is what\n-- turns \"spatial_ref_sys is world-readable\" from an alert into a decision —\n-- reading EPSG constants is harmless, but a DELETE would break every\n-- coordinate transform the charger map depends on.\n-- ---------------------------------------------------------------------------\ncreate or replace function public.debug_table_grants(p_table text)\nreturns table (grantee text, privileges text)\nlanguage sql\nsecurity definer\nset search_path = public\nas $$\n  select\n    g.grantee::text,\n    string_agg(g.privilege_type, ', ' order by g.privilege_type)::text\n  from information_schema.role_table_grants g\n  where g.table_schema = 'public'\n    and g.table_name = p_table\n    and g.grantee in ('anon', 'authenticated', 'PUBLIC')\n  group by g.grantee;\n$$;\n\n-- ---------------------------------------------------------------------------\n-- The sweep. Returns one row per table it considered.\n--\n-- Extension-owned tables are skipped, and that is what keeps this runnable:\n-- `alter table public.spatial_ref_sys` fails with \"must be owner\" for the\n-- migration role, and a statement that aborts would take the real fixes with\n-- it. Anything else that cannot be altered is caught per table and reported\n-- rather than raised.\n-- ---------------------------------------------------------------------------\ncreate or replace function public.debug_enable_rls_everywhere()\nreturns table (table_name text, action text)\nlanguage plpgsql\nsecurity definer\nset search_path = public\nas $$\ndeclare\n  t record;\nbegin\n  for t in\n    select c.oid, c.relname,\n           exists (select 1 from pg_depend d where d.objid = c.oid and d.deptype = 'e') as from_extension\n    from pg_class c\n    join pg_namespace n on n.oid = c.relnamespace\n    where n.nspname = 'public'\n      and c.relkind = 'r'\n      and c.relrowsecurity = false\n    order by c.relname\n  loop\n    if t.from_extension then\n      table_name := t.relname; action := 'skipped — owned by an extension';\n      return next;\n      continue;\n    end if;\n\n    begin\n      execute format('alter table public.%I enable row level security', t.relname);\n      table_name := t.relname; action := 'RLS enabled';\n      return next;\n    exception when insufficient_privilege then\n      table_name := t.relname;\n      action := format('skipped — not owned by %s', current_user);\n      return next;\n    end;\n  end loop;\nend $$;\n\nrevoke all on function public.debug_rls_status() from public, anon, authenticated;\nrevoke all on function public.debug_table_grants(text) from public, anon, authenticated;\nrevoke all on function public.debug_enable_rls_everywhere() from public, anon, authenticated;\ngrant execute on function public.debug_rls_status() to service_role;\ngrant execute on function public.debug_table_grants(text) to service_role;\ngrant execute on function public.debug_enable_rls_everywhere() to service_role;\n\n-- Run it once, now. Applying the migration is meant to fix the thing, not just\n-- install the ability to.\nselect public.debug_enable_rls_everywhere();\n"
  },
  {
    "id": "049_profiles_email_lookup",
    "description": "profiles.email + index — sign-in stops scanning users and stops duplicating accounts past 1000",
    "sql": "-- 049_profiles_email_lookup.sql\n--\n-- Removes a hard scaling cliff on the sign-in path.\n--\n-- Two places resolve a Supabase user id from an email address, and both do it\n-- by paging through `auth.admin.listUsers({ perPage: 100 })` until they find a\n-- match, capped at ten pages:\n--\n--   src/lib/auth.ts:73          — every Google sign-in\n--   src/lib/supabase/ensure-user.ts:55 — every write route that needs the id\n--\n-- That is up to ten sequential admin API round-trips on a login. Slow is the\n-- lesser problem. At 1001 users the scan silently fails to find an existing\n-- account and `auth.ts` falls through to `createUser`, which means a returning\n-- user gets a SECOND account and loses every vehicle, document and cost record\n-- attached to the first. Nothing errors; it just looks like the data vanished.\n--\n-- `profiles` already mirrors `auth.users` through the handle_new_user trigger.\n-- Adding the email there makes the lookup one indexed query with no cap.\n--\n-- The column is a mirror, never a source of truth: auth.users owns the address,\n-- and the trigger below keeps this copy in step on insert and on update (an\n-- email change previously left the profile row stale forever, because the\n-- trigger only fired on insert).\n\nalter table public.profiles\n  add column if not exists email text;\n\n-- Backfill what already exists. auth.users is readable from a migration.\nupdate public.profiles p\nset email = u.email\nfrom auth.users u\nwhere u.id = p.id\n  and p.email is distinct from u.email;\n\n-- Case-insensitive, because addresses are compared lowercased everywhere in the\n-- app and a unique index on the raw value would let Alice@ and alice@ coexist.\ncreate unique index if not exists profiles_email_key\n  on public.profiles (lower(email))\n  where email is not null;\n\n-- Now also fires on update: an address change used to leave this copy stale.\ncreate or replace function public.handle_new_user()\nreturns trigger\nlanguage plpgsql\nsecurity definer set search_path = public\nas $$\nbegin\n  insert into public.profiles (id, full_name, avatar_url, email)\n  values (\n    new.id,\n    new.raw_user_meta_data->>'full_name',\n    new.raw_user_meta_data->>'avatar_url',\n    new.email\n  )\n  on conflict (id) do update\n    set email = excluded.email,\n        full_name = coalesce(public.profiles.full_name, excluded.full_name),\n        avatar_url = coalesce(public.profiles.avatar_url, excluded.avatar_url);\n  return new;\nend;\n$$;\n\ndrop trigger if exists on_auth_user_created on auth.users;\ncreate trigger on_auth_user_created\n  after insert or update of email on auth.users\n  for each row execute procedure public.handle_new_user();\n\nrevoke all on function public.handle_new_user() from public, anon, authenticated;\n"
  },
  {
    "id": "050_vehicles_trim_badge",
    "description": "Remembers what the car said it is, so the answer survives the car sleeping.",
    "sql": "-- 050_vehicles_trim_badge.sql\n--\n-- Remembers what the car said it is, so the answer survives the car sleeping.\n--\n-- `vehicle_config.trim_badging` arrives with every live read and tells us two\n-- things nothing else can: the rated range a state-of-health estimate should be\n-- measured against, and the battery chemistry — which decides whether the right\n-- daily advice is \"keep it between 50 and 80%\" (NMC) or \"take it to 100% every\n-- week\" (LFP). Those are opposite instructions, so getting it from the car\n-- rather than guessing is the whole point.\n--\n-- The problem is that a parked Tesla is asleep most of the time, and a sleeping\n-- car is answered from `vehicle_snapshots`, which never carried the badge. So\n-- the chemistry advice and the SoH percentage appeared only during the minutes\n-- the car happened to be awake, and vanished the rest of the day — which reads\n-- as a broken feature, not as a car that is asleep.\n--\n-- The badge is a fact about the vehicle, not a reading: it does not change\n-- between polls, and it belongs on the row rather than in a time series. Stored\n-- as the key the trim table is keyed on, `car_type:trim_badging`\n-- (e.g. `model3:p74d`), so adding a trim stays one lookup and one line.\n\nalter table vehicles add column if not exists trim_badge text;\n\ncomment on column vehicles.trim_badge is\n  'car_type:trim_badging as reported by the car, e.g. model3:p74d. Source of the SoH baseline and the battery chemistry.';\n"
  },
  {
    "id": "051_spatial_ref_sys_rls",
    "description": "Closes the Supabase linter's `rls_disabled_in_public` on",
    "sql": "-- 051_spatial_ref_sys_rls.sql\n--\n-- Closes the Supabase linter's `rls_disabled_in_public` on\n-- `public.spatial_ref_sys`.\n--\n-- What the table is: PostGIS's catalogue of coordinate reference systems — the\n-- EPSG definitions every `ST_Transform` looks up. It arrives with the extension\n-- and lands in `public` because that is where PostGIS was installed. Nothing in\n-- it is ours and nothing in it is secret; the finding is real all the same,\n-- because a table in `public` with RLS off is readable by `anon` through\n-- PostgREST, and \"it is only reference data\" is exactly the reasoning that\n-- leaves the next such table exposed too.\n--\n-- Why this is not a one-liner: `spatial_ref_sys` is owned by the extension, not\n-- by us, and `ALTER TABLE ... ENABLE ROW LEVEL SECURITY` requires ownership.\n-- Depending on how the project was provisioned that statement either works or\n-- fails with `insufficient_privilege`, and a migration that dies there would\n-- block every migration after it. So it is attempted, and if it cannot be done\n-- the grants are withdrawn instead — which removes the same exposure by the\n-- other end: with no SELECT for `anon` and `authenticated`, PostgREST has\n-- nothing to serve whether RLS is on or not.\n--\n-- Safe for the app either way: every PostGIS query here runs through the\n-- service-role client, and `service_role` bypasses RLS and keeps its grants.\n\ndo $$\nbegin\n  execute 'alter table public.spatial_ref_sys enable row level security';\n  raise notice 'spatial_ref_sys: RLS enabled';\nexception\n  when insufficient_privilege or wrong_object_type then\n    raise notice 'spatial_ref_sys: not ours to alter, revoking grants instead';\nend;\n$$;\n\n-- Belt and braces, and the whole fix on a project where the ALTER was refused.\n-- PostGIS itself reads this table as the extension owner, so revoking the two\n-- PostgREST roles costs nothing.\nrevoke all on table public.spatial_ref_sys from anon, authenticated;\n\n-- If RLS did switch on, a table with no policy denies everyone who is not the\n-- owner and not BYPASSRLS. That is the intent: nobody reaches this through the\n-- API, and the server's service-role client is unaffected.\n"
  },
  {
    "id": "052_derived_activity",
    "description": "Lets trips and charging sessions be derived from `vehicle_snapshots` for a",
    "sql": "-- 052_derived_activity.sql\n--\n-- Lets trips and charging sessions be derived from `vehicle_snapshots` for a\n-- real car, instead of existing only for the simulator.\n--\n-- The gap this closes: `trips` and `charging_sessions` were written by\n-- `src/lib/mock/persistence.ts` and the history seeder, and by nothing else. So\n-- for a linked Tesla the activity feed, the savings and CO₂ tiles, the monthly\n-- consumption chart and the planner's personal-efficiency figure were\n-- **permanently empty**, and none of them said why — which is how \"7 days and\n-- 30 days show the same thing\" gets reported. They showed the same thing\n-- because both windows were empty.\n--\n-- `source` says where a row came from, so a derived row can be recomputed\n-- without touching a simulated or seeded one. It is nullable and unset on\n-- existing rows on purpose: backfilling them to 'mock' would be a guess about\n-- history, and nothing needs to know.\n--\n-- The partial unique indexes are what make derivation safe to re-run. A pass\n-- upserts on (vehicle_id, started_at), so a period that grows as more snapshots\n-- arrive updates in place rather than inserting a second copy of itself. Only\n-- derived rows are constrained: the simulator legitimately produces rows that\n-- would collide, and its behaviour must not change.\n\nalter table trips add column if not exists source text;\nalter table charging_sessions add column if not exists source text;\n\ncomment on column trips.source is\n  'Null for simulated and seeded rows; ''derived'' for rows computed from vehicle_snapshots.';\ncomment on column charging_sessions.source is\n  'Null for simulated and seeded rows; ''derived'' for rows computed from vehicle_snapshots.';\n\ncreate unique index if not exists trips_derived_key\n  on trips (vehicle_id, started_at)\n  where source = 'derived';\n\ncreate unique index if not exists charging_sessions_derived_key\n  on charging_sessions (vehicle_id, started_at)\n  where source = 'derived';\n\n-- The derivation walks snapshots oldest-first for one vehicle. The existing\n-- index is (vehicle_id, recorded_at desc), which serves that in reverse; this\n-- makes the ascending scan the derivation actually does an index scan too.\ncreate index if not exists vehicle_snapshots_vehicle_recorded_asc_idx\n  on vehicle_snapshots (vehicle_id, recorded_at);\n"
  }
];

export function findMigration(id: string): Migration | null {
  return MIGRATIONS.find((m) => m.id === id) ?? null;
}
